        { q: "Sketch a wavefront diagram for the moving car. Label the direction of motion.", marks: 2, markscheme: ["Circular wavefronts whose centres are shifted in the direction of motion (not concentric) ✓", "Wavefronts closer together in front of the car and further apart behind ✓"] },
        { q: "Explain, with reference to your diagram, why the frequency heard in front of the car is higher than the emitted frequency.", marks: 2, markscheme: ["The car moves forward between emitting successive wavefronts, so the wavelength in front is shorter ✓", "The speed of sound is unchanged, so more wavefronts reach the pedestrian per second / f = v/λ is higher ✓"] },
        { q: "State whether the frequency emitted by the horn changes as the car moves.", marks: 1, markscheme: ["No: the emitted frequency is constant; only the observed frequency changes ✓"] }
